sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var caseSysId = current.getUniqueValue();
    var instanceUrl = gs.getProperty('glide.servlet.uri');

    // 1. Search for the generated Vollmacht PDF on this case
    var grAtt = new GlideRecord('sys_attachment');
    grAtt.addQuery('table_sys_id', caseSysId);
    grAtt.addQuery('file_name', 'STARTSWITH', 'Vollmacht');
    grAtt.orderByDesc('sys_created_on');
    grAtt.query();

    if (grAtt.next()) {
        var attSysId = grAtt.getUniqueValue();
        var fileName = grAtt.getValue('file_name');
        var downloadUrl = instanceUrl + 'sys_attachment.do?sys_id=' + attSysId;

        // 2. Print an action button/link directly into the email body
        template.print('<div style="margin: 16px 0;">');
        template.print('  <a href="' + downloadUrl + '" target="_blank" style="background-color: #005f73; color: #ffffff; padding: 10px 18px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block; font-size: 13px;">');
        template.print('    📄 Download ' + fileName);
        template.print('  </a>');
        template.print('</div>');
    } else {
        // Fallback text if the file is not yet attached to the previewed record
        template.print('<p style="color: #64748b; font-style: italic;">[Power of Attorney PDF will be linked here upon generation]</p>');
    }
})(current, template, email, email_action, event);
